-- fix/perf_settings_1030.lua [PERFSET] 2026-10-30 (systems session). GENERATED by tools/perf_settings_build.py from
-- fix/perf_settings/installer.lua + ui/settings/SettingsEffectsController.lua: edit those, then rebuild. Edit mode, any place
-- that has the Settings screen (lobby, Tutorial, Matchmaking, Ranked, Test).
-- Why: the lag test (notes/lag_test_1030.md); Edward: "with the in game settings what can we turn off to lower this".
--   UIKit.SettingsData            Video > Performance: + Fewer Lights, Low Effects, Hide Far Screens; Optimized Lighting text
--   Controllers.SettingsEffectsController   replaced (old source kept in ServerStorage._PerfSetOrig for UNDO): the rows work
--                                 on every map (were lobby-only), lamp shadows off with Optimized Lighting, overrules a map's
--                                 GlobalShadows / bloom at match start, + the three new rows
--   Controllers.ExplosionController   Low Effects: no shadowed flash, fewer sparks / embers / dust / fireball, no debris chunks
-- Defaults are all off: nothing changes for a player who doesn't pick them. Smoke, steam and markers are never thinned.
-- Idempotent (second run: every line "="), checks every anchor before writing, UNDO = true puts everything back.
local UNDO = false --@UNDO
local DRY = false --@DRY
local NEW_CONTROLLER = [==[
--@@CONTROLLER
]==]
local SS = game:GetService("ServerStorage")
local ScriptEditorService = game:GetService("ScriptEditorService")
local out = {}
local function say(s) table.insert(out, s) end
local function getSrc(s) return s.Source end
local function setSrc(s, text) if not DRY then ScriptEditorService:UpdateSourceAsync(s, function() return text end) end end
local function find(path)
	local inst = game
	for seg in string.gmatch(path, "[^/]+") do inst = inst and inst:FindFirstChild(seg) end
	return inst
end
local function plainReplace(src, a, b)
	local i, j = string.find(src, a, 1, true)
	if not i then return nil end
	if string.find(src, a, j + 1, true) then return nil end
	return src:sub(1, i - 1) .. b .. src:sub(j + 1)
end

local data = find("ReplicatedStorage/UIKit/SettingsData")
local ctrl = find("StarterPlayer/StarterPlayerScripts/Client/Controllers/SettingsEffectsController")
local expl = find("StarterPlayer/StarterPlayerScripts/Client/Controllers/ExplosionController")
if not (data and ctrl) then return "REFUSED: no SettingsData / SettingsEffectsController in this place" end

-- 1. SettingsData rows ---------------------------------------------------------------------------------------------
local OLD_LIGHT = [[{ kind = "toggle", name = "Optimized Lighting", icon = "lightbulb", value = false, desc = "Uses simpler lighting so the game runs faster on older devices" },]]
local NEW_LIGHT = [[{ kind = "toggle", name = "Optimized Lighting", icon = "lightbulb", value = false, desc = "Turns off shadows (sun and lamps) and glow so the game runs faster on older devices" }, -- [PERFSET] text]]
local TEX_ROW = [[{ kind = "toggle", name = "Optimized Textures", icon = "texture", gen = "row_texture", value = false, desc = "Swaps detailed surface images for plain colours to save memory" },]]
local NEW_ROWS = {
	[[{ kind = "toggle", name = "Fewer Lights", icon = "lightbulb", value = false, desc = "Turns off lamps far away from you so the game runs faster" }, -- [PERFSET] ]],
	[[{ kind = "toggle", name = "Low Effects", icon = "muzzle", value = false, desc = "Smaller explosions: fewer sparks and no flying debris. Smoke stays the same" }, -- [PERFSET] ]],
	[[{ kind = "toggle", name = "Hide Far Screens", icon = "window", value = false, desc = "Signs and screens far away stop drawing" }, -- [PERFSET] ]],
}
local ADD = ""
for _, r in NEW_ROWS do ADD ..= "\n\t\t\t\t" .. r end

-- 2. ExplosionController edits (plain text: old -> new) ------------------------------------------------------------
local EXPL = {
	{ "local scale = barrel and 1 or 0.75", "local scale = barrel and 1 or 0.75\n\tlocal low = localPlayer:GetAttribute(\"Setting_LowEffects\") == true -- [PERFSET] Video > Low Effects" },
	{ "light.Shadows = true", "light.Shadows = not low -- [PERFSET] a shadowed flash re-renders the shadow maps" },
	{ ":Emit(barrel and 26 or 16)", ":Emit(low and 8 or (barrel and 26 or 16)) -- [PERFSET]" },
	{ ":Emit(barrel and 90 or 60)", ":Emit(low and 18 or (barrel and 90 or 60)) -- [PERFSET]" },
	{ ":Emit(40)", ":Emit(low and 10 or 40) -- [PERFSET]" },
	{ ":Emit(30)", ":Emit(low and 10 or 30) -- [PERFSET]" },
	{ "for i = 1, (barrel and 9 or 4) do", "for i = 1, (low and 0 or (barrel and 9 or 4)) do -- [PERFSET] no debris with Low Effects" },
}

local park = SS:FindFirstChild("_PerfSetOrig")
if UNDO then
	if not park then return "UNDO: nothing to undo (no ServerStorage._PerfSetOrig)" end
	local d = getSrc(data)
	d = plainReplace(d, TEX_ROW .. ADD, TEX_ROW) or d
	d = plainReplace(d, NEW_LIGHT, OLD_LIGHT) or d
	setSrc(data, d); say("SettingsData restored")
	local orig = park:FindFirstChild("SettingsEffectsController")
	if orig then setSrc(ctrl, orig.Value); say("SettingsEffectsController restored") end
	if expl then
		local e = getSrc(expl)
		for i = #EXPL, 1, -1 do e = plainReplace(e, EXPL[i][2], EXPL[i][1]) or e end
		setSrc(expl, e); say("ExplosionController restored")
	end
	if not DRY then park:Destroy() end
	return table.concat(out, "\n")
end

-- check everything before writing anything
local d = getSrc(data)
local dataDone = string.find(d, TEX_ROW .. ADD, 1, true) ~= nil and string.find(d, NEW_LIGHT, 1, true) ~= nil
if not dataDone and not (plainReplace(d, TEX_ROW, TEX_ROW) and plainReplace(d, OLD_LIGHT, OLD_LIGHT)) then return "REFUSED: SettingsData anchors not found" end
local c = getSrc(ctrl)
local ctrlDone = c == NEW_CONTROLLER
if not ctrlDone and (string.find(c, "[PERFSET]", 1, true) or not string.find(c, "local hiddenMap -- the LobbyMap those belong to", 1, true)) then
	return "REFUSED: SettingsEffectsController is not the version this installer knows (or another [PERFSET] round)"
end
local e = expl and getSrc(expl)
local explDone = e ~= nil and string.find(e, "[PERFSET]", 1, true) ~= nil
if e and not explDone then
	for _, pair in EXPL do if not plainReplace(e, pair[1], pair[2]) then return "REFUSED: ExplosionController anchor " .. pair[1] end end
end

if not park and not DRY then
	park = Instance.new("Folder")
	park.Name = "_PerfSetOrig"
	park:SetAttribute("Note", "[PERFSET] fix/perf_settings_1030.lua: originals for UNDO")
	local v = Instance.new("StringValue")
	v.Name = "SettingsEffectsController"
	v.Value = c
	v.Parent = park
	park.Parent = SS
end
if dataDone then say("= SettingsData") else
	d = plainReplace(d, OLD_LIGHT, NEW_LIGHT)
	d = plainReplace(d, TEX_ROW, TEX_ROW .. ADD)
	setSrc(data, d)
	say("+ SettingsData: 3 rows, Optimized Lighting text")
end
if ctrlDone then say("= SettingsEffectsController") else setSrc(ctrl, NEW_CONTROLLER); say("+ SettingsEffectsController replaced") end
if not expl then say("- no ExplosionController here")
elseif explDone then say("= ExplosionController")
else
	for _, pair in EXPL do e = plainReplace(e, pair[1], pair[2]) end
	setSrc(expl, e)
	say("+ ExplosionController: " .. #EXPL .. " edits")
end
return (DRY and "DRY " or "") .. table.concat(out, "\n")
